import{_ as t,C as o,o as r,c,a2 as s,E as i}from"./chunks/framework.kOe0DhAP.js";const f=JSON.parse('{"title":"业务概述与系统架构","description":"合约交易的核心是持仓、保证金和风险控制。","frontmatter":{"title":"业务概述与系统架构","description":"合约交易的核心是持仓、保证金和风险控制。"},"headers":[],"relativePath":"07/0701/070001.md","filePath":"07/0701/070001.md"}'),n={name:"07/0701/070001.md"};function d(l,a,_,h,p,m){const e=o("Flow");return r(),c("div",null,[a[0]||(a[0]=s('<div class="doc-eyebrow">合约手册 / TGEX KNOWLEDGE BASE</div><h1 id="业务概述与系统架构" tabindex="-1">业务概述与系统架构 <a class="header-anchor" href="#业务概述与系统架构" aria-label="Permalink to &quot;业务概述与系统架构&quot;">​</a></h1><div class="doc-lead">合约交易的核心是持仓、保证金和风险控制。</div><h2 id="basics" tabindex="-1">产品与术语 <a class="header-anchor" href="#basics" aria-label="Permalink to &quot;产品与术语 {#basics}&quot;">​</a></h2><p>开多表达价格上涨方向的持仓，开空表达下跌方向的持仓，平仓终止已有敞口。杠杆影响保证金需求，但不改变同等名义敞口的市场价格波动。</p><p>工程的交易模式枚举中可见开多、开空、平多、平空。是否提供某种合约、结算币或保证金模式，应按当前启用产品确认。</p><h2 id="architecture" tabindex="-1">模块架构 <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;模块架构 {#architecture}&quot;">​</a></h2><p>合约委托、撮合和行情分别可在 coinex-contract-entrust、coinex-contract-match、coinex-contract-market 中找到对应模块。与现货相比，成交后需要处理持仓和保证金，而不是只交换两种资产。</p>',8)),i(e,{steps:["合约委托","交易与风险校验","撮合成交","持仓及保证金更新","盈亏 / 风险 / 行情刷新"]})])}const b=t(n,[["render",d]]);export{f as __pageData,b as default};
